9-5ad0-ad1d-aa8692dae673" :knowledge-point/title "Computing Expressions Involving Second-Order Partial Derivatives"}] :question/problem "Find $f_{xy}(x,y)+f_{yx}(x,y)$ given that  $f_x(x,y)=y\cos(xy)$ and $f_y(x,y)=x\cos(xy).$" :question/worked-solution "To find $f_{xy}(x,y),$ we differentiate the given first-order partial derivative $f_{x}(x,y)$ with respect to $y\mathbin{:}$

$$
\begin{aligned}{f}_{xy}(x,y) & =\frac{∂}{∂y}({f}_{x}(x,y)) \\  & =\frac{∂}{∂y}(y\operatorname{cos}⁡(xy)) \\  & =1\cdot \operatorname{cos}⁡(xy)+y(-\operatorname{sin}⁡(xy)\cdot x) \\  & =\operatorname{cos}⁡(xy)-xy\operatorname{sin}⁡(xy)\end{aligned}
$$



Similarly, to find $f_{yx}(x,y),$ we differentiate the given first-order partial derivative $f_{y}(x,y)$ with respect to $x\mathbin{:}$

$$
\begin{aligned}{f}_{yx}(x,y) & =\frac{∂}{∂x}({f}_{y}(x,y)) \\  & =\frac{∂}{∂x}(x\operatorname{cos}⁡(xy)) \\  & =1\cdot \operatorname{cos}⁡(xy)+x(-\operatorname{sin}⁡(xy)\cdot y) \\  & =\operatorname{cos}⁡(xy)-xy\operatorname{sin}⁡(xy)\end{aligned}
$$

Therefore, we have

$$
\begin{aligned}{f}_{xy}(x,y)+{f}_{yx}(x,y) & =\operatorname{cos}⁡(xy)-xy\operatorname{sin}⁡(xy)+\operatorname{cos}⁡(xy)-xy\operatorname{sin}⁡(xy) \\  & =2(\operatorname{cos}⁡(xy)-xy\operatorname{sin}⁡(xy)).\end{aligned}
$$"} {:db/id 17592186124932 :question/id #uuid "9fe7b82e-efd4-53ad-afa8-cb700e6400e0" :question/math-academy-id "q-35936" :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "01b1340c-9ea7-510e-a7fe-a5318d1aa165" :answer/type {:db/id 17592186045498} :answer/value "2{x}^{2}\operatorname{cos}⁡y" :db/id 17592186421993} {:answer/id #uuid "2ea483d9-4903-536f-a106-b11346fafb16" :answer/type {:db/id 17592186045498} :answer/value "4x\operatorname{cos}⁡y" :db/id 17592186421997} {:answer/id #uuid "646a4289-2437-5a76-800d-038e82b06562" :answer/type {:db/id 17592186045498} :answer/value "x(\operatorname{cos}⁡y-\operatorname{sin}⁡y)" :db/id 17592186422000} {:answer/id #uuid "654452d8-a947-5e7b-b22c-8a13e2ef81d0" :answer/type {:db/id 17592186045498} :answer/value "2x(\operatorname{cos}⁡y+\operatorname{sin}⁡y)" :db/id 17592186422001} {:answer/id #uuid "6b0fbde1-6b7d-56c5-b32e-24ed9e9df6a2" :answer/type {:db/id 17592186045498} :answer/value "{x}^{2}\operatorname{sin}⁡y" :db/id 17592186422002}] :answer-field/correct {:db/id 17592186421997} :answer-field/id #uuid "f436de7c-3f9a-5c8c-8ef3-8a7a55ee418d" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186122192}] :question/difficulty {:db/id 17592186045487} :question/problem "Find ${f}_{xy}(x,y)+{f}_{yx}(x,y)$ given that  ${f}_{x}(x,y)=2x\operatorname{sin}⁡y$ and ${f}_{y}(x,y)={x}^{2}\operatorname{cos}⁡y.$" :question/worked-solution "To find ${f}_{xy}(x,y)$ we differentiate the given first-order partial derivative ${f}_{x}(x,y)$ with respect to $y:$

$$
\begin{aligned}{f}_{xy}(x,y) & =\frac{∂}{∂y}({f}_{x}(x,y)) \\  & =\frac{∂}{∂y}(2x\operatorname{sin}⁡y) \\  & =2x\operatorname{cos}⁡y\end{aligned}
$$

To find ${f}_{yx}(x,y)$ we differentiate the given first-order partial derivative ${f}_{y}(x,y)$ with respect to $x:$

$$
\begin{aligned}{f}_{yx}(x,y) & =\frac{∂}{∂x}({f}_{y}(x,y)) \\  & =\frac{∂}{∂x}({x}^{2}\operatorname{cos}⁡y) \\  & =2x\operatorname{cos}⁡y\end{aligned}
$$

Therefore, we have

$$
\begin{aligned}{f}_{xy}(x,y)+{f}_{yx}(x,y) & =2x\operatorname{cos}⁡y+2x\operatorname{cos}⁡y \\  & =4x\operatorname{cos}⁡y.\end{aligned}
$$"} {:db/id 17592186124946 :question/id #uuid "cb7a21d3-592c-577d-91a2-7365e19df69d" :question/math-academy-id "q-36014" :knowledge-point/_questions [{:db/id 17592186124441 :knowledge-point/id #uuid "503a0bfe-7c69-5ad0-ad1d-aa8692dae673" :knowledge-point/title "Computing Expressions Involving Second-Order Partial Derivatives"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "83707e27-9888-5a05-b515-c16b124dc827" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "(2)/((x - 3y)^{2})" :db/id 17592186122277} {:answer/id #uuid "b422ff4b-d728-5732-b61e-5bf8aa48c847" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{1}{3y - x}" :db/id 17592186122278} {:answer/id #uuid "c4822b37-84fb-530e-9f0a-09e21f75552d" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "(6)/((x - 3y)^{2})" :db/id 17592186122279} {:answer/id #uuid "dc568bf8-5611-5d70-bcbc-66e61b626e1d" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "- (3)/((x - 3y)^{2})" :db/id 17592186122280} {:answer/id #uuid "7c6cc276-2145-57b2-9886-61cb61e2147a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "- (1)/((x - 3y)^{2})" :db/id 17592186122281}] :answer-field/id #uuid "c063a337-38aa-5596-b563-e9c7e99c9b17" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186122276}] :question/problem "Find $g_{xy}(x, y) + g_{xx}(x, y)$ given that $g_{x}(x, y) = \frac{1}{x - 3y}$."} {:db/id 17592186268918 :question/id #uuid "aff3c98c-3437-5c9a-af97-e9221f961ad1" :question/math-academy-id "q-132875"} {:db/id 17592186268919 :question/id #uuid "607d6de3-387d-52a2-8e01-8c94e83518ce" :question/math-academy-id "q-132891"} {:db/id 17592186268920 :question/id #uuid "3aaf83dc-c135-54d5-b395-8dc2f637ad0a" :question/math-academy-id "q-132894" :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "573ca17f-8b55-50aa-b136-59bd043a6536" :answer/type {:db/id 17592186045498} :answer/value "\sqrt{3}-\pi " :db/id 17592186266921} {:answer/id #uuid "5df633bf-d9fe-5623-9aed-bd0cc78f2d1c" :answer/type {:db/id 17592186045498} :answer/value "\sqrt{3}" :db/id 17592186266974} {:answer/id #uuid "5fc7ddd0-7d66-560f-b925-d71f0a4f1da7" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{2}(\sqrt{3}+\pi )" :db/id 17592186266989} {:answer/id #uuid "75e2d132-79e6-565d-b0a0-3480a84f1042" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{2}(\pi -\sqrt{3})" :db/id 17592186267184} {:answer/id #uuid "aa6cc2bf-6cc9-5989-82ab-f94ca56c41d2" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{2}(\sqrt{3}-\frac{\pi }{3})" :db/id 17592186267685}] :answer-field/correct {:db/id 17592186266974} :answer-field/id #uuid "0722938f-1bbb-5341-b742-6808aa83c68d" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186268418}] :question/difficulty {:db/id 17592186045486} :question/problem "Find ${g}_{xx}(x,y)-{g}_{yy}(x,y)$ at $(\frac{\pi }{3},\frac{\pi }{3})$ given that ${g}_{x}(x,y)=x\operatorname{sin}⁡(x+y)-\operatorname{cos}⁡(x+y)$ and ${g}_{y}(x,y)=x\operatorname{sin}⁡(x+y).$" :question/worked-solution "To find ${g}_{xx}(x,y)$ we differentiate the given first-order partial derivative ${g}_{x}(x,y)$ with respect to $x:$

$$
\begin{aligned}{g}_{xx}(x,y) & =\frac{∂}{∂x}({g}_{x}(x,y)) \\  & =\frac{∂}{∂x}(x\operatorname{sin}⁡(x+y)-\operatorname{cos}⁡(x+y)) \\  & =\operatorname{sin}⁡(x+y)+x\operatorname{cos}⁡(x+y)+\operatorname{sin}⁡(x+y) \\  & =2\operatorname{sin}⁡(x+y)+x\operatorname{cos}⁡(x+y)\end{aligned}
$$



To find ${g}_{yy}(x,y)$ we differentiate the given first-order partial derivative ${g}_{y}(x,y)$ with respect to $y:$

$$
\begin{aligned}{g}_{yy}(x,y) & =\frac{∂}{∂y}({g}_{y}(x,y)) \\  & =\frac{∂}{∂y}(x\operatorname{sin}⁡(x+y)) \\  & =x\operatorname{cos}⁡(x+y)\end{aligned}
$$



Next, we evaluate ${g}_{xx}(x,y)$ and ${g}_{yy}(x,y)$ at $(\frac{\pi }{3},\frac{\pi }{3}):$

$$
\begin{aligned}{g}_{xx}(\frac{\pi }{3},\frac{\pi }{3}) & =2\operatorname{sin}⁡(\frac{\pi }{3}+\frac{\pi }{3})+\frac{\pi }{3}\operatorname{cos}⁡(\frac{\pi }{3}+\frac{\pi }{3})=\sqrt{3}-\frac{\pi }{6} \\ {g}_{yy}(\frac{\pi }{3},\frac{\pi }{3}) & =\frac{\pi }{3}\operatorname{cos}⁡(\frac{\pi }{3}+\frac{\pi }{3})=-\frac{\pi }{6}\end{aligned}
$$

Finally, we have

$$
{g}_{xx}(\frac{\pi }{3},\frac{\pi }{3})-{g}_{yy}(\frac{\pi }{3},\frac{\pi }{3})=\sqrt{3}-\frac{\pi }{6}-(-\frac{\pi }{6})=\sqrt{3}.
$$"} {:db/id 17592186268921 :question/id #uuid "619c15a9-a007-5612-9fb8-0f8afb4a8030" :question/math-academy-id "q-132897" :knowledge-point/_questions [{:db/id 17592186124441 :knowledge-point/id #uuid "503a0bfe-7c69-5ad0-ad1d-aa8692dae673" :knowledge-point/title "Computing Expressions Involving Second-Order Partial Derivatives"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "425cb3a9-f31d-5278-9378-bf08a38df305" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "9" :db/id 17592186266736} {:answer/id #uuid "9699bfda-ed01-5720-9988-afda1b34872c" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-1" :db/id 17592186267488} {:answer/id #uuid "990d9a0d-8a39-5f51-984b-24694aab44b1" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{2}{9}" :db/id 17592186267524} {:answer/id #uuid "da971629-e1c3-50eb-9d91-0e12040ebfe3" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{4}{9}" :db/id 17592186268079} {:answer/id #uuid "e9be40d0-3c94-561e-8513-6c2f10a0b74b" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{1}{9}" :db/id 17592186268223}] :answer-field/correct {:answer/id #uuid "da971629-e1c3-50eb-9d91-0e12040ebfe3" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{4}{9}" :db/id 17592186268079} :answer-field/id #uuid "baf0e05b-fa61-5e4e-9f86-28b1336165d5" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186268736}] :question/difficulty {:db/id 17592186045486 :db/ident :question.difficulty/hard} :question/problem "Find ${g}_{xy}(x,y)+{g}_{yx}(x,y)$ at $(-1,2)$ given that ${g}_{x}(x,y)=\frac{1}{x+2y}$ and ${g}_{y}(x,y)=\frac{2}{x+2y}.$" :question/worked-solution "To find ${g}_{xy}(x,y)$ we differentiate the given first-order partial derivative ${g}_{x}(x,y)$ with respect to $y:$

$$
\begin{aligned}{g}_{xy}(x,y) & =\frac{∂}{∂y}({g}_{x}(x,y)) \\  & =\frac{∂}{∂y}(\frac{1}{x+2y}) \\  & =-\frac{2}{(x+2y)^{2}}\end{aligned}
$$



To find ${g}_{yx}(x,y)$ we differentiate the given first-order partial derivative ${g}_{y}(x,y)$ with respect to $x:$

$$
\begin{aligned}{g}_{yx}(x,y) & =\frac{∂}{∂x}({g}_{y}(x,y)) \\  & =\frac{∂}{∂x}(\frac{2}{x+2y}) \\  & =-\frac{2}{(x+2y)^{2}}\end{aligned}
$$



Next, we evaluate ${g}_{xy}(x,y)$ and ${g}_{yx}(x,y)$ at $(-1,2):$

$$
\begin{aligned}{g}_{xy}(-1,2) & =-\frac{2}{((-1)+2(2))^{2}}=-\frac{2}{9} \\ {g}_{yx}(-1,2) & =-\frac{2}{((-1)+2(2))^{2}}=-\frac{2}{9}\end{aligned}
$$

Finally, we have

$$
{g}_{xy}(-1,2)+{g}_{yx}(-1,2)=-\frac{4}{9}.
$$"} {:db/id 17592186348378 :question/id #uuid "afef13bf-72ea-50e0-9df2-d85aa9be21e5" :question/math-academy-id "q-80403"} {:db/id 17592186348384 :question/id #uuid "0067d163-3060-585d-9cac-2338577d165d" :question/math-academy-id "q-80456"} {:db/id 17592186348391 :question/id #uuid "3a379c4d-6975-5a4f-a1f2-d51e99e08ac7" :question/math-academy-id "q-80468"} {:db/id 17592186348392 :question/id #uuid "3cbdca8a-7538-57ef-93a7-e4f6f9084490" :question/math-academy-id "q-80469"} {:db/id 17592186382379 :question/id #uuid "b4318c10-0a8e-5140-827c-8a0c895809ae" :question/math-academy-id "q-80466"} {:db/id 17592186382386 :question/id #uuid "0d39e98a-42b8-56d2-88b4-63d088086c8a" :question/math-academy-id "q-80473" :knowledge-point/_questions [{:db/id 17592186124441 :knowledge-point/id #uuid "503a0bfe-7c69-5ad0-ad1d-aa8692dae673" :knowledge-point/title "Computing Expressions Involving Second-Order Partial Derivatives"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "ef4a7ac8-061e-5af9-9fb0-ab5773165579" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{5}{3}" :db/id 17592186382388} {:answer/id #uuid "c4001b21-7575-5835-8086-75b8d29921b9" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{2}{3}" :db/id 17592186382389} {:answer/id #uuid "5d0ca7b1-e77a-5b9b-b8a5-4b9e8d84089f" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{1}{3}" :db/id 17592186382390} {:answer/id #uuid "41d02635-e49d-571a-96b0-1ac0a22b8838" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{2}{9}" :db/id 17592186382391} {:answer/id #uuid "6d245bf1-3343-5515-adf6-f1ffb3caa8af" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{5}{9}" :db/id 17592186382392}] :answer-field/correct {:answer/id #uuid "6d245bf1-3343-5515-adf6-f1ffb3caa8af" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{5}{9}" :db/id 17592186382392} :answer-field/id #uuid "2cf99c29-b792-5f2e-8440-d3e8129e97bc" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186382387}] :question/difficulty {:db/id 17592186045486 :db/ident :question.difficulty/hard} :question/problem "Find ${g}_{xx}(x,y)+{g}_{yy}(x,y)$ at $(1,-1)$ given that ${g}_{x}(x,y)=\frac{2}{2x-y}$ and ${g}_{y}(x,y)=-\frac{1}{2x-y}.$" :question/worked-solution "To find ${g}_{xx}(x,y)$ we differentiate the given first-order partial derivative ${g}_{x}(x,y)$ with respect to $x:$

$$
\begin{aligned}{g}_{xx}(x,y) & =\frac{∂}{∂x}({g}_{x}(x,y)) \\  & =\frac{∂}{∂x}(\frac{2}{2x-y}) \\  & =-\frac{4}{(2x-y)^{2}}\end{aligned}
$$



To find ${g}_{yy}(x,y)$ we differentiate the given first-order partial derivative ${g}_{y}(x,y)$ with respect to $y:$

$$
\begin{aligned}{g}_{yy}(x,y) & =\frac{∂}{∂y}({g}_{y}(x,y)) \\  & =\frac{∂}{∂y}(-\frac{1}{2x-y}) \\  & =-\frac{1}{(2x-y)^{2}}\end{aligned}
$$



Next, we evaluate ${g}_{xx}(x,y)$ and ${g}_{yy}(x,y)$ at $(1,-1):$

$$
\begin{aligned}{g}_{xx}(1,-1) & =-\frac{4}{(2(1)-(-1))^{2}}=-\frac{4}{9} \\ {g}_{yy}(1,-1) & =-\frac{1}{(2(1)-(-1))^{2}}=-\frac{1}{9}\end{aligned}
$$

Finally, we have

$$
{g}_{xx}(1,-1)+{g}_{yy}(1,-1)=-\frac{4}{9}-\frac{1}{9}=-\frac{5}{9}.
$$"} {:db/id 17592186124442 :knowledge-point/canonical-example {:db/id 17592186124246 :question/id #uuid "a41bfb06-4372-5124-b910-4b35f19d148b" :question/math-academy-id "e-3130"} :knowledge-point/id #uuid "83724b66-0f15-5b94-9576-76e9dfd56d38" :knowledge-point/questions [{:db/id 17592186124939 :question/id #uuid "ca6dfc54-54dd-5d46-99aa-e23ca5426a6a" :question/math-academy-id "q-35969"} {:db/id 17592186124948 :question/id #uuid "83167862-effb-539c-8ffb-5705b88d44f1" :question/math-academy-id "q-36019"} {:db/id 17592186268922 :question/id #uuid "e5449d51-c794-5d29-87ea-e1688a095f9f" :question/math-academy-id "q-132940"} {:db/id 17592186268923 :question/id #uuid "01b2f238-4be0-502a-a439-500d85cd72b9" :question/math-academy-id "q-132961"} {:db/id 17592186268924 :question/id #uuid "5eef046b-e675-5de1-b784-361653847836" :question/math-academy-id "q-132984"} {:db/id 17592186335787 :question/id #uuid "101d6e00-46ae-511e-8fb6-40ece63bbd97" :question/math-academy-id "q-65068"} {:db/id 17592186335788 :question/id #uuid "ab0f3803-2840-52ec-8174-767389c2fcc7" :question/math-academy-id "q-65071"} {:db/id 17592186348393 :question/id #uuid "09777d76-95e6-5bbb-83f0-f307b490599a" :question/math-academy-id "q-80474"} {:db/id 17592186381062 :question/id #uuid "a11d21f8-cefe-5922-beca-1c00b4452f90" :question/math-academy-id "q-132972"} {:db/id 17592186381069 :question/id #uuid "928e0d06-b25e-50d0-bfa3-2bcab1a87684" :question/math-academy-id "q-132973"} {:db/id 17592186382131 :question/id #uuid "8e077530-5170-5947-9234-14cb46d5f480" :question/math-academy-id "q-65052"} {:db/id 17592186422010 :question/id #uuid "11508c24-c4aa-589a-b2fa-c4b12396bfe7" :question/math-academy-id "q-65070"} {:db/id 17592186422011 :question/id #uuid "fdce2d33-30de-52e0-89c4-590147a8c4ea" :question/math-academy-id "q-80479"}] :knowledge-point/title "Finding Higher-Order Derivatives"} {:db/id 17592186124246 :question/id #uuid "a41bfb06-4372-5124-b910-4b35f19d148b" :question/math-academy-id "e-3130" :knowledge-point/_canonical-example [{:db/id 17592186124442 :knowledge-point/id #uuid "83724b66-0f15-5b94-9576-76e9dfd56d38" :knowledge-point/title "Finding Higher-Order Derivatives"}] :question/problem "Evaluate $g_{xyz}(x,y,z)$ at $(1,2,3)$ if $g_x(x,y,z) = 2x y z +  y^3.$" :question/worked-solution "First, we find $g_{xy}(x,y,z)$ by differentiating $g_{x}(x,y,z)$ with respect to $y\mathbin{:}$

$$
\begin{aligned}{g}_{xy}(x,y,z) & =\frac{∂}{∂y}(2xyz+{y}^{3}) \\  & =2xz+3{y}^{2}\end{aligned}
$$

Next, we find $g_{xyz}(x,y,z)$ by differentiating $g_{xy}(x,y,z)$ with respect to $z\mathbin{:}$

$$
\begin{aligned}{g}_{xyz}(x,y,z) & =\frac{∂}{∂z}(2xz+3{y}^{2}) \\  & =2x\end{aligned}
$$

Finally, we obtain 

$$
\begin{aligned}{g}_{xyz}(1,2,3) & =2(1) \\  & =2.\end{aligned}
$$"} {:db/id 17592186124939 :question/id #uuid "ca6dfc54-54dd-5d46-99aa-e23ca5426a6a" :question/math-academy-id "q-35969" :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "9137d290-41b5-56f3-91a0-1bd21a361f51" :answer/type {:db/id 17592186045498} :answer/value "2x" :db/id 17592186122235} {:answer/id #uuid "9a8c61f9-4828-5963-94b5-9c4024267fa6" :answer/type {:db/id 17592186045498} :answer/value "2" :db/id 17592186122236} {:answer/id #uuid "fb781ced-0c22-5194-a9bf-5a48f6b0b287" :answer/type {:db/id 17592186045498} :answer/value "\frac{2}{y}" :db/id 17592186122237} {:answer/id #uuid "54475861-eeaf-5969-a8d8-c01e85facc65" :answer/type {:db/id 17592186045498} :answer/value "0" :db/id 17592186122238} {:answer/id #uuid "74a0e08c-a99c-5a0d-80ac-df9b1bbcc42b" :answer/type {:db/id 17592186045498} :answer/value "\frac{2}{x}" :db/id 17592186122239}] :answer-field/correct {:db/id 17592186122236} :answer-field/id #uuid "0485544a-7efe-5a7c-a375-d04fc25e6208" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186122234}] :question/difficulty {:db/id 17592186045485} :question/problem "Calculate ${f}_{xyx}(x,y)$ given that $f(x,y)={x}^{2}y+{y}^{2}\operatorname{ln}⁡y.$" :question/worked-solution "First, we find the first-order derivative ${f}_{x}(x,y):$

$$
\begin{aligned}{f}_{x}(x,y) & =\frac{∂}{∂x}({x}^{2}y+{y}^{2}\operatorname{ln}⁡y) \\  & =2xy\end{aligned}
$$

Next, we find ${f}_{xy}(x,y)$ by differentiating ${f}_{x}(x,y)$ with respect to $y:$

$$
\begin{aligned}{f}_{xy}(x,y) & =\frac{∂}{∂y}({f}_{x}(x,y)) \\  & =\frac{∂}{∂y}(2xy) \\  & =2x\end{aligned}
$$

Finally, we find ${f}_{xyx}(x,y)$ by differentiating ${f}_{xy}(x,y)$ with respect to $x:$ 

$$
\begin{aligned}{f}_{xyx}(x,y) & =\frac{∂}{∂x}({f}_{xy}(x,y)) \\  & =\frac{∂}{∂x}(2x) \\  & =2\end{aligned}
$$"} {:db/id 17592186124948 :question/id #uuid "83167862-effb-539c-8ffb-5705b88d44f1" :question/math-academy-id "q-36019" :knowledge-point/_questions [{:db/id 17592186124442 :knowledge-point/id #uuid "83724b66-0f15-5b94-9576-76e9dfd56d38" :knowledge-point/title "Finding Higher-Order Derivatives"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "0ac03de1-652b-5985-829a-d4f563b4f013" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{1}{3}" :db/id 17592186321231} {:answer/id #uuid "185580bd-9cc6-5540-8ee1-1837bdfe77d2" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-1" :db/id 17592186321341} {:answer/id #uuid "22497853-7a4b-5053-82a4-7c884988d174" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "3" :db/id 17592186321407} {:answer/id #uuid "68d3f72b-f450-57bb-a925-2dc21238378a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0" :db/id 17592186321966} {:answer/id #uuid "e54d78bf-547b-50fd-9032-1d545e85b3e4" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "1" :db/id 17592186322943}] :answer-field/correct {:answer/id #uuid "22497853-7a4b-5053-82a4-7c884988d174" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "3" :db/id 17592186321407} :answer-field/id #uuid "a755a285-5a12-5e67-b7c4-bee828c410d0" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186323491}] :question/difficulty {:db/id 17592186045486 :db/ident :question.difficulty/hard} :question/problem "Evaluate ${f}_{xyz}(1,1,1)$ for $f(x,y,z)=\frac{yz}{x-2z}.$" :question/worked-solution "First, we find the first-order derivative ${f}_{x}(x,y,z):$

$$
\begin{aligned}{f}_{x}(x,y,z) & =\frac{∂}{∂x}(\frac{yz}{x-2z}) \\  & =-\frac{yz}{(x-2z)^{2}}\end{aligned}
$$

Now, we find ${f}_{xy}(x,y,z)$ by differentiating ${f}_{x}(x,y,z)$ with respect to $y:$

$$
\begin{aligned}{f}_{xy}(x,y,z) & =\frac{∂}{∂y}({f}_{x}(x,y,z)) \\  & =\frac{∂}{∂y}(-\frac{yz}{(x-2z)^{2}}) \\  & =-\frac{z}{(x-2z)^{2}}\end{aligned}
$$

Next, we find ${f}_{xyz}(x,y,z)$ by differentiating ${f}_{xy}(x,y,z)$ with respect to $z:$ 

$$
\begin{aligned}{f}_{xyz}(x,y,z) & =\frac{∂}{∂z}({f}_{xy}(x,y,z)) \\  & =\frac{∂}{∂z}(-\frac{z}{(x-2z)^{2}}) \\  & =-\frac{1\cdot (x-2z)^{2}-z\cdot 2(x-2z)\cdot (-2)}{(x-2z)^{4}} \\  & =-\frac{(x-2z)^{2}+4z(x-2z)}{(x-2z)^{4}} \\  & =-\frac{x-2z+4z}{(x-2z)^{3}} \\  & =-\frac{x+2z}{(x-2z)^{3}}\end{aligned}
$$

Finally, we evaluate ${f}_{xyz}(x,y,z)$ at $(1,1,1):$

$$
\begin{aligned}{f}_{xyz}(1,1,1) & =-\frac{1+2\cdot 1}{(1-2\cdot 1)^{3}}=3\end{aligned}
$$"} {:db/id 17592186268922 :question/id #uuid "e5449d51-c794-5d29-87ea-e1688a095f9f" :question/math-academy-id "q-132940"} {:db/id 17592186268923 :question/id #uuid "01b2f238-4be0-502a-a439-500d85cd72b9" :question/math-academy-id "q-132961"} {:db/id 17592186268924 :question/id #uuid "5eef046b-e675-5de1-b784-361653847836" :question/math-academy-id "q-132984"} {:db/id 17592186335787 :question/id #uuid "101d6e00-46ae-511e-8fb6-40ece63bbd97" :question/math-academy-id "q-65068"} {:db/id 17592186335788 :question/id #uuid "ab0f3803-2840-52ec-8174-767389c2fcc7" :question/math-academy-id "q-65071"} {:db/id 17592186348393 :question/id #uuid "09777d76-95e6-5bbb-83f0-f307b490599a" :question/math-academy-id "q-80474"} {:db/id 17592186381062 :question/id #uuid "a11d21f8-cefe-5922-beca-1c00b4452f90" :question/math-academy-id "q-132972"} {:db/id 17592186381069 :question/id #uuid "928e0d06-b25e-50d0-bfa3-2bcab1a87684" :question/math-academy-id "q-132973" :knowledge-point/_questions [{:db/id 17592186124442 :knowledge-point/id #uuid "83724b66-0f15-5b94-9576-76e9dfd56d38" :knowledge-point/title "Finding Higher-Order Derivatives"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "03d5b128-9cff-50f7-92d3-d12b64c6681f" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{8}" :db/id 17592186381071} {:answer/id #uuid "a441ccb0-2f8a-535a-ad8a-583f492794d1" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{2}{9}" :db/id 17592186381072} {:answer/id #uuid "a34ca82a-d861-5b5f-9369-497429efb02c" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{1}{8}" :db/id 17592186381073} {:answer/id #uuid "005be97c-3318-5160-8963-0e2dca0a9c0a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{1}{16}" :db/id 17592186381074} {:answer/id #uuid "84c1f9d1-ec7c-53d8-90d2-3e9b6975372f" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{16}" :db/id 17592186381075}] :answer-field/correct {:answer/id #uuid "a34ca82a-d861-5b5f-9369-497429efb02c" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{1}{8}" :db/id 17592186381073} :answer-field/id #uuid "3208b2b5-bf53-54c6-b739-ef239137d627" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186381070}] :question/difficulty {:db/id 17592186045486 :db/ident :question.difficulty/hard} :question/problem "Evaluate ${f}_{zxx}(1,0,1)$ for $f(x,y,z)=\frac{z}{x+z}.$" :question/worked-solution "First, we find the first-order derivative ${f}_{z}(x,y,z):$

$$
\begin{aligned}{f}_{z}(x,y,z) & =\frac{∂}{∂z}(\frac{z}{x+z}) \\  & =\frac{x}{(x+z)^{2}}\end{aligned}
$$

Now, we find ${f}_{zx}(x,y,z)$ by differentiating ${f}_{z}(x,y,z)$ with respect to $x:$

$$
\begin{aligned}{f}_{zx}(x,y,z) & =\frac{∂}{∂x}({f}_{z}(x,y,z)) \\  & =\frac{∂}{∂x}(\frac{x}{(x+z)^{2}}) \\  & =\frac{(x+z)^{2}-2x(x+z)}{(x+z)^{4}} \\  & =\frac{z-x}{(x+z)^{3}}\end{aligned}
$$

Next, we find ${f}_{zxx}(x,y,z)$ by differentiating ${f}_{zx}(x,y,z)$ with respect to $x:$ 

$$
\begin{aligned}{f}_{zxx}(x,y,z) & =\frac{∂}{∂x}({f}_{zy}(x,y,z)) \\  & =\frac{∂}{∂x}(\frac{z-x}{(x+z)^{3}}) \\  & =\frac{-(x+z)^{3}-3(z-x)(x+z)^{2}}{(x+z)^{6}} \\  & =\frac{2(x-2z)}{(x+z)^{4}}\end{aligned}
$$



Finally, we evaluate ${f}_{zxx}(x,y,z)$ at $(1,0,1):$  

$$
\begin{aligned}{f}_{zxx}(1,0,1) & =\frac{2(1-2(1))}{(1+1)^{4}}=\frac{-2}{16}=-\frac{1}{8}\end{aligned}
$$"} {:db/id 17592186382131 :question/id #uuid "8e077530-5170-5947-9234-14cb46d5f480" :question/math-academy-id "q-65052"} {:db/id 17592186422010 :question/id #uuid "11508c24-c4aa-589a-b2fa-c4b12396bfe7" :question/math-academy-id "q-65070" :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "07b7ad2e-54cc-50e3-9ca3-0b8efd17be6d" :answer/type {:db/id 17592186045498} :answer/value "4y+{e}^{x}" :db/id 17592186421994} {:answer/id #uuid "1f109dc7-15d8-584f-8e2b-595762c1a061" :answer/type {:db/id 17592186045498} :answer/value "4xy+y{e}^{x}" :db/id 17592186421996} {:answer/id #uuid "44455996-432d-5a3d-8b99-8ba088ea40bc" :answer/type {:db/id 17592186045498} :answer/value "2xy+{e}^{x}" :db/id 17592186421998} {:answer/id #uuid "5e886d04-bc8d-58c5-9141-d4629aa452fc" :answer/type {:db/id 17592186045498} :answer/value "x{y}^{2}+y{e}^{x}" :db/id 17592186421999} {:answer/id #uuid "e3c5be38-2517-52b4-89a2-e748dfb3f71f" :answer/type {:db/id 17592186045498} :answer/value "y+x+{e}^{x}" :db/id 17592186422007}] :answer-field/correct {:db/id 17592186421994} :answer-field/id #uuid "31dfaa29-640a-5223-927a-6d7e182b7cd8" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186422009}] :question/difficulty {:db/id 17592186045485} :question/problem "Calculate ${f}_{xyx}(x,y)$ given that $f(x,y)={x}^{2}{y}^{2}+y{e}^{x}.$" :question/worked-solution "First, we find the first-order derivative ${f}_{x}(x,y):$ 

$$
\begin{aligned}{f}_{x}(x,y) & =\frac{∂}{∂x}({x}^{2}{y}^{2}+y{e}^{x}) \\  & =2x\cdot {y}^{2}+y\cdot {e}^{x} \\  & =2x{y}^{2}+y{e}^{x}\end{aligned}
$$

Next, we find ${f}_{xy}(x,y)$ by differentiating ${f}_{x}(x,y)$ with respect to $y:$

$$
\begin{aligned}{f}_{xy}(x,y) & =\frac{∂}{∂y}({f}_{x}(x,y)) \\  & =\frac{∂}{∂y}(2x{y}^{2}+y{e}^{x}) \\  & =2x\cdot 2y+1\cdot {e}^{x} \\  & =4xy+{e}^{x}\end{aligned}
$$

Finally, we find ${f}_{xyx}(x,y)$ by differentiating ${f}_{xy}(x,y)$ with respect to $x:$ 

$$
\begin{aligned}{f}_{xyx}(x,y) & =\frac{∂}{∂x}({f}_{xy}(x,y)) \\  & =\frac{∂}{∂x}(4xy+{e}^{x}) \\  & =4\cdot 1\cdot y+{e}^{x} \\  & =4y+{e}^{x}\end{aligned}
$$"} {:db/id 17592186422011 :question/id #uuid "fdce2d33-30de-52e0-89c4-590147a8c4ea" :question/math-academy-id "q-80479" :knowledge-point/_questions [{:db/id 17592186124442 :knowledge-point/id #uuid "83724b66-0f15-5b94-9576-76e9dfd56d38" :knowledge-point/title "Finding Higher-Order Derivatives"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "1c70e303-c80e-51d2-8821-2af0cf8b3950" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "2y\operatorname{cos}⁡({y}^{2})-x\operatorname{sin}⁡({y}^{2})" :db/id 17592186421995} {:answer/id #uuid "92245356-2a0e-55cd-8484-17313be9c3ed" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "{y}^{2}\operatorname{cos}⁡({y}^{2})-2x\operatorname{sin}⁡({y}^{2})" :db/id 17592186422003} {:answer/id #uuid "992b5993-493b-561e-9033-5437b3de59e0" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "{y}^{2}\operatorname{cos}⁡({y}^{2})" :db/id 17592186422004} {:answer/id #uuid "ca872c1a-6f89-5f8b-8336-d7cb854e1bcb" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "4x{y}^{2}\operatorname{sin}⁡({y}^{2})" :db/id 17592186422005} {:answer/id #uuid "d1afdc0c-1cf1-54cf-9c95-d81dfb59dc49" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "4y\operatorname{cos}⁡({y}^{2})" :db/id 17592186422006}] :answer-field/correct {:answer/id #uuid "d1afdc0c-1cf1-54cf-9c95-d81dfb59dc49" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "4y\operatorname{cos}⁡({y}^{2})" :db/id 17592186422006} :answer-field/id #uuid "1a95cb7d-93f6-5084-ade9-1c85a3b6b1f1" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186422008}] :question/difficulty {:db/id 17592186045485 :db/ident :question.difficulty/easy} :question/problem "Calculate ${g}_{xxy}(x,y)$ given that $g(x,y)=({x}^{2}+y)\operatorname{sin}⁡({y}^{2}).$" :question/worked-solution "First, we find the first-order derivative ${g}_{x}(x,y):$ 

$$
\begin{aligned}{g}_{x}(x,y) & =\frac{∂}{∂x}(({x}^{2}+y)\operatorname{sin}⁡({y}^{2})) \\  & =2x\operatorname{sin}⁡({y}^{2})\end{aligned}
$$

Next, we find ${g}_{x}(x,y)$ by differentiating ${g}_{x}(x,y)$ with respect to $x:$

$$
\begin{aligned}{g}_{xx}(x,y) & =\frac{∂}{∂x}({g}_{x}(x,y)) \\  & =\frac{∂}{∂x}(2x\operatorname{sin}⁡({y}^{2})) \\  & =2\operatorname{sin}⁡({y}^{2})\end{aligned}
$$

Finally, we find ${g}_{xxy}(x,y)$ by differentiating ${g}_{xx}(x,y)$ with respect to $y:$ 

