d #uuid "6d245bf1-3343-5515-adf6-f1ffb3caa8af" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{5}{9}" :db/id 17592186382392} {:answer-field/choices [{:answer/id #uuid "1c70e303-c80e-51d2-8821-2af0cf8b3950" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "2y\operatorname{cos}⁡({y}^{2})-x\operatorname{sin}⁡({y}^{2})" :db/id 17592186421995} {:answer/id #uuid "92245356-2a0e-55cd-8484-17313be9c3ed" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "{y}^{2}\operatorname{cos}⁡({y}^{2})-2x\operatorname{sin}⁡({y}^{2})" :db/id 17592186422003} {:answer/id #uuid "992b5993-493b-561e-9033-5437b3de59e0" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "{y}^{2}\operatorname{cos}⁡({y}^{2})" :db/id 17592186422004} {:answer/id #uuid "ca872c1a-6f89-5f8b-8336-d7cb854e1bcb" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "4x{y}^{2}\operatorname{sin}⁡({y}^{2})" :db/id 17592186422005} {:answer/id #uuid "d1afdc0c-1cf1-54cf-9c95-d81dfb59dc49" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "4y\operatorname{cos}⁡({y}^{2})" :db/id 17592186422006}] :answer-field/correct {:answer/id #uuid "d1afdc0c-1cf1-54cf-9c95-d81dfb59dc49" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "4y\operatorname{cos}⁡({y}^{2})" :db/id 17592186422006} :answer-field/id #uuid "1a95cb7d-93f6-5084-ade9-1c85a3b6b1f1" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186422008} {:answer/id #uuid "1c70e303-c80e-51d2-8821-2af0cf8b3950" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "2y\operatorname{cos}⁡({y}^{2})-x\operatorname{sin}⁡({y}^{2})" :db/id 17592186421995} {:answer/id #uuid "92245356-2a0e-55cd-8484-17313be9c3ed" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "{y}^{2}\operatorname{cos}⁡({y}^{2})-2x\operatorname{sin}⁡({y}^{2})" :db/id 17592186422003} {:answer/id #uuid "992b5993-493b-561e-9033-5437b3de59e0" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "{y}^{2}\operatorname{cos}⁡({y}^{2})" :db/id 17592186422004} {:answer/id #uuid "ca872c1a-6f89-5f8b-8336-d7cb854e1bcb" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "4x{y}^{2}\operatorname{sin}⁡({y}^{2})" :db/id 17592186422005} {:answer/id #uuid "d1afdc0c-1cf1-54cf-9c95-d81dfb59dc49" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "4y\operatorname{cos}⁡({y}^{2})" :db/id 17592186422006} {:activity/first-step {:db/id 17592186125269} :activity/id #uuid "c9d087b0-e0c7-5257-8039-6b926add5c2f" :activity/scope {:db/id 17592186048781 :topic/id #uuid "be3a8d83-d961-5a49-82b6-e2c59f1bcd4b" :topic/math-academy-id 1933} :activity/steps [{:db/id 17592186125269 :step/content {:db/id 17592186125724 :tutorial/content "Just like we can compute second derivatives of single-variable functions, we can also compute second derivatives of multivariable functions.

For example, consider the two-variable function

$$
f (x, y)= x y^2 + e^{xy}.
$$

Its two first-order partial derivatives are

$$
\begin{aligned}{f}_{x}(x,y) & ={y}^{2}+y{e}^{xy}, \\ {f}_{y}(x,y) & =2xy+x{e}^{xy}.\end{aligned}
$$

Since $f_x(x,y)$ and $f_y(x,y)$ are themselves functions that are differentiable with respect to both $x$ and $y,$ we can compute the **second-order partial derivatives** as well. 

- The partial derivatives of $f_x(x,y)$ with respect to $x$ and $y,$ denoted $f_{xx}$ and $f_{xy}$ respectively, are

$$
\begin{aligned}{f}_{xx}(x,y) & =\frac{∂}{∂x}({f}_{x}(x,y))={y}^{2}{e}^{xy}, \\ {f}_{xy}(x,y) & =\frac{∂}{∂y}({f}_{x}(x,y))=2y+xy{e}^{xy}+{e}^{xy}.\end{aligned}
$$

- The partial derivatives of $f_y(x,y)$ with respect to $x$ and $y,$ denoted $f_{yx}$ and $f_{yy}$ respectively, are

$$
\begin{aligned}{f}_{yx}(x,y) & =\frac{∂}{∂x}({f}_{y}(x,y))=2y+xy{e}^{xy}+{e}^{xy}, \\ {f}_{yy}(x,y) & =\frac{∂}{∂y}({f}_{y}(x,y))=2x+{x}^{2}{e}^{xy}.\end{aligned}
$$

The partial derivatives $f_{xy}$ and $f_{yx}$ are called **mixed partial derivatives** because they involve taking the partial derivatives with respect to different variables, $x$ and $y.$

The following alternative notations are also widely used to represent second-order partial derivatives:

$$
\begin{aligned}\frac{{∂}^{2}}{∂{x}^{2}}(f) & =\frac{{∂}^{2}f}{∂{x}^{2}}={f}_{xx}\,\,\,\,\,\frac{{∂}^{2}}{∂{y}^{2}}(f)=\frac{{∂}^{2}f}{∂{y}^{2}}={f}_{yy} \\ \frac{{∂}^{2}}{∂y\,∂x}(f) & =\frac{{∂}^{2}f}{∂y\,∂x}={f}_{xy}\,\frac{{∂}^{2}}{∂x\,∂y}(f)=\frac{{∂}^{2}f}{∂x\,∂y}={f}_{yx}\end{aligned}
$$

**Note:** In our example, the two mixed partial derivatives were equal:

$$
f_{xy}(x,y) = 2y + xye^{xy} + e^{xy} = f_{yx}(x,y)
$$

Later, we will see that under rather mild conditions on $f,$ we almost always have that $f_{xy}=f_{yx}.$" :tutorial/id #uuid "feb54aa0-17fb-5468-8b99-14174a6bd059" :tutorial/math-academy-id 2397 :tutorial/title "Introduction"} :step/id #uuid "0eaae658-c43c-5756-80c4-c4462162b555" :step/math-academy-id 10558 :step/next {:db/id 17592186125270}} {:db/id 17592186125270 :step/content {:db/id 17592186124440 :knowledge-point/canonical-example {:db/id 17592186124244 :question/id #uuid "0a8f5141-941d-5059-9d9f-bf9e5b09096f" :question/math-academy-id "e-3127"} :knowledge-point/id #uuid "7ea31275-77bd-59c7-8e1d-96e2e4b252a4" :knowledge-point/key-prerequisites [{:db/id 17592186048707} {:db/id 17592186050902}] :knowledge-point/questions [{:db/id 17592186124935} {:db/id 17592186125185} {:db/id 17592186235546} {:db/id 17592186268915} {:db/id 17592186268916} {:db/id 17592186335782} {:db/id 17592186335784} {:db/id 17592186348377} {:db/id 17592186382138} {:db/id 17592186382358} {:db/id 17592186382365} {:db/id 17592186382372}] :knowledge-point/title "Finding Mixed Second-Order Partial Derivatives"} :step/id #uuid "4f4f64aa-ab4f-5abb-8d9c-ca2aa2790b64" :step/math-academy-id 10559 :step/next {:db/id 17592186125271}} {:db/id 17592186125271 :step/content {:db/id 17592186124441 :knowledge-point/canonical-example {:db/id 17592186124245 :question/id #uuid "e16f6686-dffb-554e-a50a-8760e818439f" :question/math-academy-id "e-3129"} :knowledge-point/id #uuid "503a0bfe-7c69-5ad0-ad1d-aa8692dae673" :knowledge-point/questions [{:db/id 17592186124932} {:db/id 17592186124946} {:db/id 17592186268918} {:db/id 17592186268919} {:db/id 17592186268920} {:db/id 17592186268921} {:db/id 17592186348378} {:db/id 17592186348384} {:db/id 17592186348391} {:db/id 17592186348392} {:db/id 17592186382379} {:db/id 17592186382386}] :knowledge-point/title "Computing Expressions Involving Second-Order Partial Derivatives"} :step/id #uuid "a25341f7-8d06-561b-9802-42d2f9c792e8" :step/math-academy-id 10563 :step/next {:db/id 17592186125272}} {:db/id 17592186125272 :step/content {:db/id 17592186125725 :tutorial/content "We can also define other **higher order partial derivatives** such as $f_{xxy}, \, f_{xxyy}, \, f_{xyxy},$ etc. 

For instance, the function $f(x,y,z)= z\cos(xy)$ has the first-order partial derivative

$$
f_y(x,y,z) = -xz \sin(xy)
$$

and the second-order partial derivative

$$
f_{yx}(x,y,z)= -x yz \cos{\left(x y \right)} - z\sin{\left(x y \right)}.
$$

If we differentiate again, with respect to $x,$ then we get the **third-order partial derivative** $f_{yxx}\mathbin{:}$ 

$$
\begin{aligned}{f}_{yxx}(x,y,z) & =\frac{∂}{∂x}({f}_{yx}(x,y)) \\  & =\frac{∂}{∂x}(-xyz\operatorname{cos}(xy)-z\operatorname{sin}(xy)) \\  & =-yz\operatorname{cos}(xy)-xyz(-\operatorname{sin}(xy)\cdot y)-z\operatorname{cos}(xy)\cdot y \\  & =x{y}^{2}z\operatorname{sin}(xy)-2yz\operatorname{cos}(xy)\end{aligned}
$$

In general, to compute a $n$th-order partial derivative, we need to compute a sequence of $n$ individual derivatives." :tutorial/id #uuid "e256986d-ca95-50b3-a16c-0f46005b5c66" :tutorial/math-academy-id 2398 :tutorial/title "Higher-Order Partial Derivatives for Functions of  More Than Two Variables"} :step/id #uuid "f8b4cf47-e81c-516c-8eef-7d544743362a" :step/math-academy-id 10566 :step/next {:db/id 17592186125273}} {:db/id 17592186125273 :step/content {:db/id 17592186124442 :knowledge-point/canonical-example {:db/id 17592186124246 :question/id #uuid "a41bfb06-4372-5124-b910-4b35f19d148b" :question/math-academy-id "e-3130"} :knowledge-point/id #uuid "83724b66-0f15-5b94-9576-76e9dfd56d38" :knowledge-point/questions [{:db/id 17592186124939} {:db/id 17592186124948} {:db/id 17592186268922} {:db/id 17592186268923} {:db/id 17592186268924} {:db/id 17592186335787} {:db/id 17592186335788} {:db/id 17592186348393} {:db/id 17592186381062} {:db/id 17592186381069} {:db/id 17592186382131} {:db/id 17592186422010} {:db/id 17592186422011}] :knowledge-point/title "Finding Higher-Order Derivatives"} :step/id #uuid "25a77626-7a96-5d1b-b087-a01012cbeb91" :step/math-academy-id 10567}] :activity/title "Higher-Order Partial Derivatives" :activity/type {:db/id 17592186045463 :db/ident :activity.type/lesson} :db/id 17592186124726} {:db/id 17592186125269 :step/content {:db/id 17592186125724 :tutorial/content "Just like we can compute second derivatives of single-variable functions, we can also compute second derivatives of multivariable functions.

